  2: "Vital Statistics and Health",
  3: "Education",
  4: "Law Enforcement, Courts, and Prisons",
  5: "Geography and Environment",
  6: "Land Use and Ownership",
  7: "Recreation and Travel",
  8: "Elections",
  9: "Government Finances and Employment",
  10: "National Defense",
  11: "Social Insurance and Human Services",
  12: "Labor Force, Employment, and Earnings",
  13: "Income, Expenditures, and Wealth",
  14: "Prices",
  15: "Banking, Insurance, and Business Enterprise",
  16: "Information and Communications",
  17: "Energy and Science",
  18: "Transportation",
