function colLetter(cellAddr: string): string {
  const m = cellAddr.match(/!\$?([A-Z]+)\$?\d+$/);
  return m ? m[1] : "";
}

function measurementKey(
  panel: number,
  rowDims: string[],
  colDims: string[],
): string {
  return JSON.stringify([panel, rowDims.map(labelKey), colDims.map(labelKey)]);
}

interface Draft {
  key: string;
  panel: number;
  panelLabel: string;
  rowDims: string[];
  colDims: string[];
  firstCol: string;
  cells: Assigned[];
}

export interface ProposeOptions {
  narratives?: Record<number, string>;
  previous?: ManifestSection[];
}

/** Build the manifest from the 2025 edition IR. */
export function propose(
  ir: EditionIR,
  opts: ProposeOptions = {},
): ManifestSection[] {
  const previousPrefix = new Map<string, string>();
  for (const sec of opts.previous ?? []) {
    for (const t of sec.tables) {
      for (const m of t.measurements) {
        previousPrefix.set(`${t.tableNum}|${m.key}`, m.prefix);
      }
    }
  }

  const cellsByTable = new Map<string, IRCell[]>();
  for (const c of ir.cells) {
    let list = cellsByTable.get(c.tableNum);
    if (!list) cellsByTable.set(c.tableNum, (list = []));
    list.push(c);
  }

  const sections = new Map<number, ManifestSection>();
  const usedPrefixes = new Set<string>();
  for (const table of [...ir.tables].sort((a, b) =>
    a.tableNum.localeCompare(b.tableNum),
  )) {
    if (!["long", "wide", "snapshot"].includes(table.layout)) continue;
    const cells = cellsByTable.get(table.tableNum) ?? [];
    if (cells.length === 0) continue;
    const mt = proposeTable(table, cells, previousPrefix, usedPrefixes);
    if (mt.measurements.length === 0) continue;
    let sec = sections.get(table.section);
    if (!sec) {
      sections.set(
        table.section,
        (sec = {
          section: table.section,
          name: SECTION_NAMES[table.section] ?? `Section ${table.section}`,
          narrative: opts.narratives?.[table.section] ?? "",
          tables: [],
        }),
      );
    }
    sec.tables.push(mt);
  }
  return [...sections.values()].sort((a, b) => a.section - b.section);
}

function proposeTable(
  table: IRTable,
  cells: IRCell[],
  previousPrefix: Map<string, string>,
  usedPrefixes: Set<string>,
): ManifestTable {
  const assigned = assignGeo(cells);
  const idents = panelIdentities(table);
  const drafts = new Map<string, Draft>();
  for (const a of assigned) {
    const ident = idents.get(a.cell.panel) ?? { id: a.cell.panel, label: "" };
    const key = measurementKey(ident.id, a.rowDims, a.colDims);
    let d = drafts.get(key);
    if (!d) {
      drafts.set(
        key,
        (d = {
          key,
          panel: ident.id,
          panelLabel: ident.label,
          rowDims: a.rowDims,
          colDims: a.colDims,
          firstCol: colLetter(a.cell.cellAddr),
          cells: [],
        }),
      );
    }
    d.cells.push(a);
  }

  // Prefixes: DB{SSTT}[P{n}][R{nn}][{col letter}], col letter only when needed.
  const base = `DB${table.tableNum.replace(".", "")}`;
  const rowOrdinal = new Map<string, number>();
  const groupOf = (d: Draft) => {
    const p = d.panel > 0 ? `P${d.panel + 1}` : "";
    if (d.rowDims.length === 0) return `${base}${p}`;
    const rk = `${d.panel}|${JSON.stringify(d.rowDims.map(labelKey))}`;
    if (!rowOrdinal.has(rk)) {
      const n =
        [...rowOrdinal.keys()].filter((k) => k.startsWith(`${d.panel}|`))
          .length + 1;
      rowOrdinal.set(rk, n);
    }
    return `${base}${p}R${String(rowOrdinal.get(rk)).padStart(2, "0")}`;
  };
  const groups = new Map<string, Draft[]>();
  for (const d of drafts.values()) {
    const g = groupOf(d);
    groups.set(g, [...(groups.get(g) ?? []), d]);
  }
  const prefixOf = new Map<Draft, string>();
  for (const [g, ds] of groups) {
    if (ds.length === 1) {
      prefixOf.set(ds[0], g);
      continue;
    }
    const seen = new Map<string, number>();
    for (const d of ds) {
      let p = `${g}${d.firstCol}`;
      const n = seen.get(p) ?? 0;
      seen.set(p, n + 1);
      if (n > 0) p = `${p}${n + 1}`;
      prefixOf.set(d, p);
    }
  }

  const title = titleCase(table.title);
  const draftList = [...drafts.values()];
  const rowHeader = (d: Draft) =>
    table.panels.find((p) => p.index === d.panel)?.headers[0]?.[0] ?? "";
  const portals = portalNames(
    draftList.map((d) => ({ ...d, rowHeader: rowHeader(d) })),
    table.title,
  );
  const measurements: ManifestMeasurement[] = [];
  for (const [di, d] of draftList.entries()) {
    let prefix =
      previousPrefix.get(`${table.tableNum}|${d.key}`) ?? prefixOf.get(d)!;
    while (usedPrefixes.has(prefix)) prefix = `${prefix}X`;
    usedPrefixes.add(prefix);

    const parts = [d.panelLabel, ...d.rowDims, ...d.colDims].filter(Boolean);
    const cellsOnly = d.cells.map((a) => a.cell);
    const numFmt = majority(
      cellsOnly.map((c) => c.numFmt).filter((f): f is string => !!f),
    );
    const percent = isPercentFormat(numFmt);
    const decimals = formatDecimals(numFmt) ?? guessDecimals(cellsOnly);
    const basis = basisNote(cellsOnly);
    const portal = portals[di];
    const description = describe(table.title, d, basis);
    const footnoteMarkers = [
      ...new Set(cellsOnly.flatMap((c) => c.markers)),
    ].filter((m) => table.footnotes[m]);

    const series = new Map<string, ManifestSeries>();
    for (const a of d.cells) {
      if (series.has(a.geo)) continue;
      series.set(a.geo, {
        name: `${prefix}@${a.geo}.A`,
        geo: a.geo,
        locator: {
          panel: d.panel,
          rowPath: a.cell.rowPath,
          colPath: a.cell.colPath,
        },
        snapshot: table.layout === "snapshot",
      });
    }

    measurements.push({
      prefix,
      key: d.key,
      dataPortalName: portal,
      description,
      unit: inferUnit({
        headnote: table.headnote,
        labels: parts,
        numFmt,
        percent,
      }),
      percent,
      decimals,
      indent:
        table.layout === "long"
          ? 0
          : Math.min(3, Math.max(0, d.rowDims.length - 1)),
      footnoteMarkers,
      series: [...series.values()],
    });
  }

  return {
    tableNum: table.tableNum,
    title,
    titlePeriod: table.titlePeriod,
    layout: table.layout,
    headnote: table.headnote,
    footnotes: table.footnotes,
    source: {
      agency: DATABOOK_SOURCE,
      link: DATABOOK_URL,
      detail: truncate(
        `Data Book Table ${Number(table.tableNum.slice(0, 2))}.${table.tableNum.slice(3)} (${table.edition} edition). Original source: ${table.source
          .replace(/^\s*sources?:\s*/i, "")
          .replace(/\s+/g, " ")
          .trim()}`,
        1000,
      ),
      originalAgency: sourceAgency(table.source),
      originalLink: table.sourceUrl,
    },
    measurements,
  };
}

function majority<T>(xs: T[]): T | undefined {
  const counts = new Map<T, number>();
  for (const x of xs) counts.set(x, (counts.get(x) ?? 0) + 1);
  return [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0];
}

function guessDecimals(cells: IRCell[]): number {
  let max = 0;
  for (const c of cells) {
    const s = String(c.value);
    const dot = s.indexOf(".");
    if (dot >= 0) max = Math.max(max, Math.min(3, s.length - dot - 1));
  }
  return max;
}

function truncate(s: string, n: number): string {
  return s.length <= n ? s : s.slice(0, n - 1) + "…";
}

// ─── Persistence ────────────────────────────────────────────────────

/**
 * Lives next to the vintage file in data-dir (gitignored; ~25 MB for
 * ~37k candidate series). Names stay frozen because `propose` always
 * starts from the previous manifest — keep this directory backed up.
 */
export function manifestDir(): string {
  return join(databookDir(), "manifest");
}

/** Measurement notes: the table headnote plus its applicable footnotes. */
export function measurementNotes(
  t: ManifestTable,
  m: ManifestMeasurement,
): string {
  return [
    t.headnote,
    ...m.footnoteMarkers.map((k) => `[${k}] ${t.footnotes[k]}`),
  ]
    .filter(Boolean)
    .join("\n");
}

export function writeManifest(
  sections: ManifestSection[],
  dir = manifestDir(),
): void {
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  for (const s of sections) {
    writeFileSync(
      join(dir, `section${String(s.section).padStart(2, "0")}.json`),
      JSON.stringify(s) + "\n",
    );
  }
}

export function readManifest(dir = manifestDir()): ManifestSection[] {
  const out: ManifestSection[] = [];
  for (let i = 1; i <= 24; i++) {
    const f = join(dir, `section${String(i).padStart(2, "0")}.json`);
    if (existsSync(f)) out.push(JSON.parse(readFileSync(f, "utf8")));
  }
  return out;
}

/** All manifest series, flattened, with their measurement and table. */
export function allSeries(sections: ManifestSection[]) {
  return sections.flatMap((s) =>
    s.tables.flatMap((t) =>
      t.measurements.flatMap((m) =>
        m.series.map((series) => ({
          section: s,
          table: t,
          measurement: m,
          series,
        })),
      ),
    ),
  );
}
